import java.util.*;

class Solution {
    private static class Node {
        Node[] next = new Node[26];
        boolean isEnd;
    }

    public boolean canSplit(String text, String[] dict) {
        Node root = new Node();
        for (String w : dict) {               // build the dictionary trie
            Node cur = root;
            for (char c : w.toCharArray()) {
                int k = c - 'a';
                if (cur.next[k] == null) cur.next[k] = new Node();
                cur = cur.next[k];
            }
            cur.isEnd = true;
        }
        int n = text.length();
        boolean[] ok = new boolean[n + 1];    // ok[i]: first i letters can be split
        ok[0] = true;
        for (int i = 0; i < n; i++) {
            if (!ok[i]) continue;
            Node cur = root;
            for (int j = i; j < n; j++) {     // walk the trie along text from i
                cur = cur.next[text.charAt(j) - 'a'];
                if (cur == null) break;
                if (cur.isEnd) ok[j + 1] = true; // text[i..j] is a word
            }
        }
        return ok[n];
    }
}

