class Solution:
    def canSplit(self, text: str, dict: List[str]) -> bool:
        ws = set(dict); L = max(map(len, ws)); n = len(text)
        ok = [True] + [False] * n
        for i in range(1, n + 1):
            for j in range(max(0, i - L), i):
                if ok[j] and text[j:i] in ws: ok[i] = True; break
        return ok[n]

