function canSplit(text, dict) {
  const memo = new Map(), ws = new Set(dict);
  const go = i => {
    if (i === text.length) return true;
    if (memo.has(i)) return memo.get(i);
    let r = false;
    for (let j = i + 1; j <= text.length && !r; j++) if (ws.has(text.slice(i, j))) r = go(j);
    memo.set(i, r); return r;
  };
  return go(0);
}
